document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("laminate-form"),t=document.getElementById("laminate-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("laminate-area").value),a=parseFloat(document.getElementById("laminate-pack").value),o=parseFloat(document.getElementById("laminate-waste").value)||0;if(n<=0||a<=0)return t.textContent="Please enter room area and coverage per box.",void 0;const r=n*(1+o/100),s=Math.ceil(r/a),i=s*a,l=i-n,d=l/n*100;t.innerHTML=`\n        <div class="result-section">\n          <h4>Laminate Flooring Needed:</h4>\n          <p><strong>${s} boxes</strong> required</p>\n          <p>Total coverage: ${i.toFixed(0)} sq ft</p>\n          <p>Room area: ${n} sq ft</p>\n        </div>\n        <div class="result-details">\n          <h4>Material Breakdown:</h4>\n          <p>Base area: ${n} sq ft</p>\n          <p>With ${o}% waste factor: ${r.toFixed(1)} sq ft</p>\n          <p>Extra material for future repairs: ${l.toFixed(1)} sq ft (${d.toFixed(1)}%)</p>\n        </div>\n        <div class="result-tips">\n          <p><em>📦 Each box covers ${a} sq ft</em></p>\n          <p><em>✨ Store extra planks in a dry place for future repairs</em></p>\n          <p><em>🔍 Check all boxes for defects before installation</em></p>\n        </div>\n      `})});